const fs = require('fs');
const path = require('path');

// Function to read environment variables from .env.test
function loadEnvFromFile(envFilePath) {
  if (!fs.existsSync(envFilePath)) {
    console.log(`Environment file '${envFilePath}' does not exist.`);
    return {};
  }

  const envContent = fs.readFileSync(envFilePath, 'utf8');
  const envVars = {};

  envContent.split('\n').forEach(line => {
    // Skip empty lines and comments
    if (line.trim() === '' || line.startsWith('#')) {
      return;
    }

    const [key, ...values] = line.split('=');
    const value = values.join('=').trim().replace(/^"(.*)"$/, '$1'); // Remove surrounding quotes if present
    envVars[key.trim()] = value;
  });

  return envVars;
}

