async function sendAuditData(envVars) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(envVars);
    const url = new URL('http://localhost:47301/api/audit');

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Successfully sent audit data to migration audit service');
          resolve(data);
        } else {
          reject(new Error(`Audit service responded with status code ${res.statusCode}`));
        }
