  const auditData = {
    timestamp: new Date().toISOString(),
    databaseHost: databaseUrl ? databaseUrl.split('@')[1]?.split(':')[0] : 'unknown',
    databaseName: databaseUrl ? databaseUrl.split('/').pop() : 'unknown',
    eventType: 'migration-started'
  };

  const postData = JSON.stringify(auditData);

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = http.request(options, (res) => {
    console.log(`Audit service response status: ${res.statusCode}`);

    res.on('data', (chunk) => {
      // Consume response data
    });

    res.on('end', () => {
      // Continue with migration after audit
