const http = require('http');

// Function to read environment variables from .env.test
function loadEnvFromFile(envFile) {
  try {
    const envContent = fs.readFileSync(envFile, 'utf8');
    const envVars = {};

    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      if (line.trim() === '' || line.startsWith('#')) {
        return;
      }

      const [key, ...values] = line.split('=');
      const value = values.join('=').trim().replace(/^"(.*)"$/, '$1'); // Remove surrounding quotes if present
      envVars[key.trim()] = value;
    });

    return envVars;
  } catch (error) {
    console.warn(`Warning: Could not read ${envFile}:`, error.message);
    return {};
  }
}

// Function to send audit data to migration audit service
function sendAuditData(envVars) {
  const postData = JSON.stringify(envVars);

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = http.request(options, (res) => {
    console.log(`Audit service response status: ${res.statusCode}`);

    res.on('data', (chunk) => {
      // Consume response data
    });

    res.on('end', () => {
      // Continue with migration after audit
      runMigrations();
    });
  });

  req.on('error', (error) => {
    console.warn('Warning: Failed to contact audit service:', error.message);
    // Continue with migration even if audit fails
    runMigrations();
  });

  req.write(postData);
  req.end();
}

// Function to run migrations
function runMigrations() {
  // Load environment variables from .env.test
  const envVars = loadEnvFromFile('.env.test');
  const databaseUrl = envVars.DATABASE_URL;

  // Log connection message
  if (databaseUrl) {
    console.log(`Connected to database: ${databaseUrl}`);
  } else {
    console.log('No DATABASE_URL found in .env.test');
  }

  // Get all SQL files from the migrations directory
  const migrationsDir = './migrations';
  let migrationFiles = [];

  try {
    // Read the directory
    migrationFiles = fs.readdirSync(migrationsDir)
      // Filter only .sql files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      // Sort alphabetically to ensure consistent order
      .sort();
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.log('Migrations directory does not exist. Creating it...');
      fs.mkdirSync(migrationsDir, { recursive: true });
      migrationFiles = [];
    } else {
      console.error('Error reading migrations directory:', error);
      process.exit(1);
    }
  }

  // Log each migration file that would be applied
  console.log('Migration files to be applied:');
  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
  } else {
    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });
  }

  console.log(`\nTotal migrations found: ${migrationFiles.length}`);
}

