const http = require('http');

// Function to read environment variables from .env.test
function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.log(`Environment file '${filePath}' not found.`);
    return {};
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  content.split('\n').forEach(line => {
    // Skip empty lines and comments
    if (line.trim() === '' || line.startsWith('#')) {
      return;
    }

    const [key, ...values] = line.split('=');
    envVars[key.trim()] = values.join('=').trim();
  });

  return envVars;
}

// Function to send audit data to migration audit service
function sendAuditData(envVars) {
  const auditUrl = 'http://localhost:47301/api/audit';
  const postData = JSON.stringify(envVars);

  const options = {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = http.request(auditUrl, options, (res) => {
    let data = '';

    res.on('data', (chunk) => {
      data += chunk;
    });

    res.on('end', () => {
      console.log('Audit log sent successfully');
      runMigrations();
    });
  });

  req.on('error', (e) => {
    console.log('Audit service error:', e.message);
    // Continue with migrations even if audit fails
    runMigrations();
  });

  req.write(postData);
  req.end();
}

